<script lang="ts">
 import {onMount} from 'svelte';
 import {campaignState} from './campaign-state';
 import {settleCampaignAction,type CampaignProject} from './campaign-actions';
 import {campaignMoves,campaignActivity,adviserPrompt} from './campaign-play';
 import ResultDocument from './ResultDocument.svelte';
 let selected='',loaded='',model='gpt-5.6-sol',role='Propose',question='',busy=false,error='',notice='',messages:any[]=[];
 let adviser:HTMLDialogElement,autopilot:HTMLDialogElement;
 let reading=false;
 $: project=($campaignState.control?.projects?.find(p=>p.id===$campaignState.selectedProject)||null) as CampaignProject|null;
 $: moves=project?campaignMoves(project):[];
 $: if(project&&loaded!==project.id){loaded=project.id;selected='';messages=[];error='';notice='';question='';}
 $: move=moves.find((m:any)=>m.id===selected)||moves[0];
 $: activity=project?campaignActivity(project):null;
 $: recent=(project?.workQueue?.items||[]).filter((i:any)=>i.kind==='campaign'&&i.status==='done'&&i.results?.length).slice(-3).reverse();
 $: canMutate=$campaignState.access?.canMutate===true;
 $: loop=project?.loop;
 $: running=loop?.status==='running';
 $: resumable=Boolean(loop?.canResume)&&['paused','attention'].includes(loop?.status);
 $: canLoop=Boolean(project?.canStartLoop)||resumable;
 $: modelLabel=model==='gpt-5.6-sol'?'Sol':model==='gpt-5.6-terra'?'Terra':'Astra';
 function read(item:any,result:any){window.dispatchEvent(new CustomEvent('lane-watch:read-result',{detail:{projectId:project?.id,itemId:item.id,resultId:result.id}}));}
 async function sync(){
  if(!project?.coordinator?.attached||reading)return;
  const id=project.id;reading=true;
  try{const r=await fetch('/api/codex/conversation?project='+encodeURIComponent(id),{cache:'no-store',signal:AbortSignal.timeout(10000)});const data=await r.json();if(!r.ok)throw Error(data.error||'Could not read adviser conversation');if(project?.id===id)messages=(data.turns||[]).flatMap((t:any)=>t.messages||[]).filter((m:any)=>m.role==='assistant').slice(-3);}
  catch(e){if(project?.id===id)error=String(e);}finally{reading=false;}
 }
 function openAdvice(){adviser.showModal();void sync();}
 async function ask(){
  if(!project||busy||activity?.advising)return;const id=project.id;busy=true;error='';notice='';
  try{await settleCampaignAction({projectId:id,type:'coordinator.message.send',args:{advice:true,model,role,message:adviserPrompt(project,move,role,question)},scope:'campaign-adviser'});if(project?.id===id){notice=`${modelLabel} is considering this move. Advice will appear here; no research was launched.`;await sync();}}
  catch(e){if(project?.id===id)error=e instanceof Error?e.message:String(e);}finally{busy=false;}
 }
 async function controlLoop(){
  if(!project||busy)return;busy=true;error='';
  const action=running?'loop.pause':resumable?'loop.resume':'loop.start';
  try{await settleCampaignAction({projectId:project.id,type:action,scope:'play-autopilot'});notice=action==='loop.pause'?'Pause requested.':'Research autopilot requested.';}
  catch(e){error=e instanceof Error?e.message:String(e);}finally{busy=false;}
 }
 onMount(()=>{const timer=setInterval(()=>{if(adviser?.open)void sync();},5000);return()=>clearInterval(timer);});
</script>

{#if project}
 <section class="campaign-play" aria-label="Campaign play">
  <div class="play-heading"><div><p class="kicker">{project.id.toUpperCase()} · RESEARCH CAMPAIGN</p><h2>Find the next breakthrough.</h2><p class="mission">{project.id==='cfg23'?'Can 23 points and 23 lines each meet exactly four of the other? Build toward an answer, one useful theorem at a time.':'Choose a worthwhile question. Turn evidence into your next move.'}</p></div><button class="autopilot" onclick={()=>autopilot.showModal()}>◈ Autopilot <span>{running?'Running':'Set up'}</span></button></div>
  <div class="journey" aria-label="Research loop"><strong>01 <span>Choose a move</span></strong><span>→</span><span>02 Consult & prepare</span><span>→</span><span>03 Run & discover</span><span>→</span><span>04 Decide what’s next</span></div>
  <div class="play-grid">
   <article class="next-move">
    <p class="kicker">YOUR NEXT MOVE</p>
    <h3>{move?.title||'Choose a new campaign direction'}</h3>
    <p>{move?.detail||'Ask your adviser to propose a useful next step from the current evidence.'}</p>
    <div class="move-actions"><button class="primary" onclick={openAdvice}>Explore this move <span>↗</span></button><a href="#campaign-library" onclick={()=>{const d=document.querySelector('#campaign-library') as HTMLDetailsElement;if(d)d.open=true;}}>See the evidence</a></div>
    {#if moves.length>1}<details class="alternatives"><summary>Choose another move <span>{moves.length-1} alternatives</span></summary><div>{#each moves as option}<button class:chosen={move?.id===option.id} onclick={()=>selected=option.id}><span>{option.kind==='campaign'?'◇':'⌘'}</span>{option.title}{#if move?.id===option.id}<b>Selected</b>{/if}</button>{/each}</div></details>{/if}
   </article>
   <aside class="field-status"><p class="kicker">ON THE FIELD</p><h3>{activity?.busy?'Work is underway':'Ready when you are'}</h3><p>{activity?.advising?'Your campaign adviser is thinking.':activity?.research.length?`${activity.research.length} research run(s) in progress.`:'No research worker is running.'}</p>{#if activity?.actions.length}<p>{activity.actions.length} control action(s) pending.</p>{/if}{#if activity?.custody.length}<p>{activity.custody.length} custody item(s) in progress.</p>{/if}<div class="status-rule"></div><strong>Advice is a move, too.</strong><p>Review a proof, challenge an assumption, or learn why a result matters.</p><button onclick={openAdvice}>Consult Sol, Terra or Astra →</button><small>{project.workQueue?.heartbeat?.status==='active'?`${project.workQueue.cadenceMinutes}-minute check-ins scheduled`:'Scheduled check-ins are paused'}</small></aside>
  </div>
  <section class="discoveries" aria-label="Recent discoveries"><div class="section-title"><h3>What we’ve unlocked</h3><span>Read the result. Choose what it enables.</span></div><div class="discovery-grid">{#each recent as item}<article><span class="discovery-mark">✧</span><h4>{item.title}</h4><p>{item.detail}</p>{#each item.results.filter((r:any)=>r.path.endsWith('.md')).slice(-1) as result}<button onclick={()=>read(item,result)}>Read {result.title} ↗</button>{/each}</article>{/each}{#if !recent.length}<p>Your first completed results will appear here.</p>{/if}</div></section>
 </section>
{/if}

<dialog bind:this={adviser} class="play-dialog" aria-labelledby="adviser-title"><header><div><p class="kicker">CAMPAIGN ADVISER</p><h2 id="adviser-title">Think through your next move.</h2></div><button onclick={()=>adviser.close()} aria-label="Close adviser">×</button></header><div class="dialog-body"><p class="selected-move">{move?.title||'Campaign direction'}</p><div class="adviser-options"><label>Think with<select bind:value={model}><option value="gpt-5.6-sol">Sol</option><option value="gpt-5.6-terra">Terra</option><option value="gpt-6-astra">Astra</option></select></label><label>Help me<select bind:value={role}><option>Propose</option><option>Challenge</option><option>Explain</option><option>Synthesize</option></select></label></div><label class="question">Anything to focus on?<textarea bind:value={question} maxlength="3000" rows="3" placeholder="What would make this a convincing paper checkpoint?"></textarea></label><p class="adviser-boundary">Uses the attached Codex conversation and its context. One adviser turn; research launches and evidence acceptance stay separate. Shared context means this is not an independent audit.</p><button class="primary" disabled={!canMutate||!project?.coordinator?.attached||busy||activity?.advising} onclick={ask}>{busy?'Starting…':activity?.advising?'Adviser is thinking…':`Ask ${modelLabel}`}</button>{#if !project?.coordinator?.attached}<p>Connect a campaign coordinator in the library’s settings to enable advice.</p>{/if}{#if notice}<p role="status">{notice}</p>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="adviser-results"><div class="section-title"><h3>Conversation</h3><button disabled={reading} onclick={sync}>{reading?'Loading…':'Refresh'}</button></div>{#each messages as message}<article><ResultDocument content={String(message.text||'')}/></article>{/each}{#if !messages.length}<p>Your adviser’s replies will appear here.</p>{/if}</div><button class="secondary" onclick={()=>{adviser.close();autopilot.showModal();}}>Review research execution options →</button></div></dialog>
<dialog bind:this={autopilot} class="play-dialog" aria-labelledby="autopilot-title"><header><div><p class="kicker">BOUNDED AUTOPILOT</p><h2 id="autopilot-title">One decision-to-decision research loop.</h2></div><button onclick={()=>autopilot.close()} aria-label="Close autopilot">×</button></header><div class="dialog-body"><p>Autopilot uses the campaign’s checked plan, frozen resource limits and existing human gates. It stops at the next decision or blocking requirement.</p>{#if !running&&!canLoop}<div class="capability-hold"><strong>Research execution needs preparation</strong><p>{loop?.resumeBlocker||project?.loopStart?.blocker||'The current campaign has not cleared its launch requirements.'} Advice and evidence review are available now.</p><button class="primary" onclick={()=>{autopilot.close();openAdvice();}}>Ask an adviser instead</button></div>{:else}<button class="primary" disabled={!canMutate||busy} onclick={controlLoop}>{running?'Pause research autopilot':resumable?'Resume checked research loop':'Start checked research loop'}</button>{/if}<details><summary>Inspect launch requirements and controls</summary><p>Open the library’s “History and automation” drawer for the exact budget, schedule and current gate.</p><a href="#process-history" onclick={()=>{autopilot.close();for(const id of ['campaign-library','process-history']){const d=document.getElementById(id) as HTMLDetailsElement;if(d)d.open=true;}}}>Open launch controls →</a></details>{#if notice}<p role="status">{notice}</p>{/if}{#if error}<p role="alert">{error}</p>{/if}</div></dialog>

<style>
 .campaign-play{max-width:1280px;margin:0 auto;color:#eaf0e7;padding:20px 8px 32px}.kicker{font:600 11px/1.5 monospace;letter-spacing:.16em;color:#a6c6ac;margin:0 0 12px}.play-heading{display:flex;justify-content:space-between;gap:28px;align-items:center}.play-heading h2{font-size:clamp(30px,4vw,52px);letter-spacing:-.04em;line-height:1.1;margin:0 0 16px;font-weight:650}.mission{color:#aabfb2;max-width:650px;line-height:1.7;font-size:16px;margin:0}.autopilot{background:#d5edb0;color:#162a1c;border:0;border-radius:100px;padding:17px 24px;white-space:nowrap;font-size:16px;font-weight:650;cursor:pointer}.autopilot span{font-size:12px;margin-left:12px;opacity:.7}.journey{display:flex;gap:18px;align-items:center;margin:32px 0;color:#82988b;font-size:12px;border-top:1px solid #304737;padding-top:22px;flex-wrap:wrap}.journey strong{color:#d5edb0}.journey strong span{margin-left:8px}.play-grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(240px,1fr);gap:20px}.next-move{background:radial-gradient(ellipse at top right,#355242 0,transparent 65%),#192d23;border:1px solid #587b59;border-radius:20px;padding:30px}.next-move h3{font-size:29px;line-height:1.2;letter-spacing:-.02em;margin:0 0 16px;max-width:650px}.next-move>p:not(.kicker){line-height:1.7;color:#b9cbbf;max-width:690px;font-size:14px}.move-actions{display:flex;align-items:center;gap:24px;margin-top:25px;flex-wrap:wrap}.primary{background:#d5edb0;border:1px solid #d5edb0;border-radius:10px;color:#14251a;padding:13px 19px;font-weight:650;cursor:pointer;font-size:14px}.primary span{margin-left:22px}a{color:#c2d6bd;font-size:13px}.field-status{background:#14241d;border:1px solid #344d3b;border-radius:20px;padding:28px}.field-status h3{font-size:23px;margin:0 0 12px}.field-status p{color:#a9bdb0;line-height:1.6;font-size:14px}.status-rule{height:1px;background:#304737;margin:22px 0}.field-status button,.discoveries button,.secondary{border:0;background:none;color:#d5edb0;text-align:left;padding:10px 0;cursor:pointer;font-size:14px}.field-status small{display:block;color:#8ba291;font-size:12px;margin-top:16px}.alternatives{margin-top:28px;border-top:1px solid #3a5643;padding-top:18px;font-size:13px}.alternatives summary{cursor:pointer;display:flex;justify-content:space-between;gap:10px}.alternatives summary span{color:#9db3a4}.alternatives button{display:flex;gap:12px;width:100%;text-align:left;background:#15271c;border:1px solid transparent;border-radius:8px;padding:13px;color:#c0d0c1;margin-top:8px;cursor:pointer}.alternatives button.chosen{border-color:#88aa72}.alternatives b{margin-left:auto;font-size:10px}.section-title{display:flex;align-items:baseline;justify-content:space-between;gap:16px;flex-wrap:wrap}.section-title h3{font-size:20px}.section-title>span{color:#94ac9b;font-size:12px}.discoveries{margin-top:26px}.discovery-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.discovery-grid article{border:1px solid #344d3b;border-radius:14px;padding:23px;background:#111f19}.discovery-mark{color:#d5edb0;font-size:25px}.discovery-grid h4{font-size:17px;line-height:1.4;margin:12px 0}.discovery-grid p{color:#9db3a4;font-size:13px;line-height:1.6;display:-webkit-box;-webkit-line-clamp:3;line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.play-dialog{width:min(790px,calc(100vw - 24px));max-height:calc(100dvh - 32px);padding:0;background:#14241c;color:#eaf0e7;border:1px solid #658367;border-radius:20px}.play-dialog::backdrop{background:#050e09cf;backdrop-filter:blur(5px)}.play-dialog header{display:flex;align-items:center;justify-content:space-between;padding:25px;border-bottom:1px solid #344d3b;gap:12px}.play-dialog h2{font-size:25px;margin:0}.play-dialog header button{background:none;border:0;color:#d5edb0;font-size:28px;cursor:pointer}.dialog-body{padding:25px}.selected-move{color:#d5edb0}.adviser-options{display:flex;gap:20px}.adviser-options label{flex:1}.play-dialog label{font-size:13px;color:#adc3b1}.play-dialog select,.play-dialog textarea{display:block;width:100%;box-sizing:border-box;background:#0f1e16;color:#eaf0e7;border:1px solid #47644e;border-radius:8px;padding:12px;margin:8px 0 18px;font:inherit}.question{display:block}.adviser-boundary{color:#90a896;font-size:12px;line-height:1.6}.adviser-results article{margin-top:18px;padding:18px;border:1px solid #354f3e;border-radius:12px;overflow-wrap:anywhere}.adviser-results button{background:none;color:#c2d6bd;border:0;cursor:pointer}.error{color:#ffc0a9}.capability-hold{background:#213426;padding:22px;border-radius:12px;margin:20px 0}.play-dialog details{margin-top:24px;line-height:1.7;font-size:14px}.play-dialog summary{cursor:pointer}button:disabled{opacity:.5;cursor:not-allowed}button:focus-visible,a:focus-visible,summary:focus-visible{outline:2px solid #d5edb0;outline-offset:4px}@media(max-width:720px){.play-grid,.discovery-grid{grid-template-columns:1fr}.play-heading{align-items:flex-start;flex-direction:column}.journey{gap:10px;font-size:11px}.next-move,.field-status{padding:23px}.next-move h3{font-size:25px}.campaign-play{padding:12px 0}.play-dialog header,.dialog-body{padding:18px}}
</style>
